<?php
require_once __DIR__.'/../includes/authorization.php';require_role('admin');require_once __DIR__.'/../includes/Repositories/CategoryRepository.php';$repo=new CategoryRepository();$errors=[];
if(is_post()){if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('admin-categories'));}$action=$_POST['action']??'';try{if($action==='create'){$name=trim($_POST['name']??'');if(mb_strlen($name)<2||mb_strlen($name)>80)$errors[]='Nama kategori 2-80 karakter.';else{$repo->create($name);flash('success','Kategori dibuat.');redirect(page_url('admin-categories'));}}elseif($action==='update'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$name=trim($_POST['name']??'');$status=$_POST['status']??'';if(!$id||mb_strlen($name)<2||mb_strlen($name)>80||!in_array($status,['active','archived'],true))$errors[]='Data kategori tidak valid.';else{$repo->update((int)$id,$name,$status);flash('success','Kategori diperbarui.');redirect(page_url('admin-categories'));}}}catch(Throwable $e){$errors[]='Nama kategori sudah ada atau data tidak valid.';}}
$cats=$repo->all();$pageTitle='Kelola Kategori';require __DIR__.'/../includes/header.php';
?><section class="section-padding page-section"><div class="container"><div class="page-toolbar"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?></div><div class="section-heading mb-4"><span class="eyebrow">Admin</span><h2>Kelola <em>kategori.</em></h2><p class="text-muted">Kategori dipakai seller saat menambah produk dan customer saat memfilter katalog.</p></div><?php if($errors):?><div class="alert alert-danger"><?=implode('<br>',array_map('e',$errors))?></div><?php endif;?><div class="glass-card p-4 mb-4"><form class="row g-2" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="col-md-9"><label class="form-label">Kategori baru</label><input class="form-control" name="name" required placeholder="Contoh: Kosmetik"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Tambah kategori</button></div></form></div><?php foreach($cats as $c):?><div class="glass-card p-3 mb-3"><form class="row g-2 align-items-end" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=intval($c['id'])?>"><div class="col-md-6"><label class="form-label">Nama</label><input class="form-control" name="name" value="<?=e($c['name'])?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=$c['status']==='active'?'selected':''?>>active</option><option value="archived" <?=$c['status']==='archived'?'selected':''?>>archived</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Simpan</button></div></form></div><?php endforeach;?></div></section><?php require __DIR__.'/../includes/footer.php'; ?>